<VERSION_A>
   1 | static int pm8001_exec_internal_tmf_task(struct domain_device *dev,
   2 | 	void *parameter, u32 para_len, struct pm8001_tmf_task *tmf)
   3 | {
   4 | 	int res, retry;
   5 | 	struct sas_task *task = NULL;
   6 | 	struct pm8001_hba_info *pm8001_ha = pm8001_find_ha_by_dev(dev);
   7 | 	struct pm8001_device *pm8001_dev = dev->lldd_dev;
   8 | 	DECLARE_COMPLETION_ONSTACK(completion_setstate);
   9 | 
  10 | 	for (retry = 0; retry < 3; retry++) {
  11 | 		task = sas_alloc_slow_task(GFP_KERNEL);
  12 | 		if (!task)
  13 | 			return -ENOMEM;
  14 | 
  15 | 		task->dev = dev;
  16 | 		task->task_proto = dev->tproto;
  17 | 		memcpy(&task->ssp_task, parameter, para_len);
  18 | 		task->task_done = pm8001_task_done;
  19 | 		task->slow_task->timer.function = pm8001_tmf_timedout;
  20 | 		task->slow_task->timer.expires = jiffies + PM8001_TASK_TIMEOUT*HZ;
  21 | 		add_timer(&task->slow_task->timer);
  22 | 
  23 | 		res = pm8001_task_exec(task, GFP_KERNEL, 1, tmf);
  24 | 
  25 | 		if (res) {
  26 | 			del_timer(&task->slow_task->timer);
  27 | 			pm8001_dbg(pm8001_ha, FAIL, "Executing internal task failed\n");
  28 | 			goto ex_err;
  29 | 		}
  30 | 		wait_for_completion(&task->slow_task->completion);
  31 | 		if (pm8001_ha->chip_id != chip_8001) {
  32 | 			pm8001_dev->setds_completion = &completion_setstate;
  33 | 			PM8001_CHIP_DISP->set_dev_state_req(pm8001_ha,
  34 | 				pm8001_dev, DS_OPERATIONAL);
  35 | 			wait_for_completion(&completion_setstate);
  36 | 		}
  37 | 		res = -TMF_RESP_FUNC_FAILED;
  38 | 		/* Even TMF timed out, return direct. */
  39 | 		if (task->task_state_flags & SAS_TASK_STATE_ABORTED) {
  40 | 			struct pm8001_ccb_info *ccb = task->lldd_task;
  41 | 
  42 | 			pm8001_dbg(pm8001_ha, FAIL, "TMF task[%x]timeout.\n",
  43 | 				   tmf->tmf);
  44 | 
  45 | 			if (ccb)
  46 | 				ccb->task = NULL;
  47 | 			goto ex_err;
  48 | 		}
  49 | 
  50 | 		if (task->task_status.resp == SAS_TASK_COMPLETE &&
  51 | 			task->task_status.stat == SAS_SAM_STAT_GOOD) {
  52 | 			res = TMF_RESP_FUNC_COMPLETE;
  53 | 			break;
  54 | 		}
  55 | 
  56 | 		if (task->task_status.resp == SAS_TASK_COMPLETE &&
  57 | 		task->task_status.stat == SAS_DATA_UNDERRUN) {
  58 | 			/* no error, but return the number of bytes of
  59 | 			* underrun */
  60 | 			res = task->task_status.residual;
  61 | 			break;
  62 | 		}
  63 | 
  64 | 		if (task->task_status.resp == SAS_TASK_COMPLETE &&
  65 | 			task->task_status.stat == SAS_DATA_OVERRUN) {
  66 | 			pm8001_dbg(pm8001_ha, FAIL, "Blocked task error.\n");
  67 | 			res = -EMSGSIZE;
  68 | 			break;
  69 | 		} else {
  70 | 			pm8001_dbg(pm8001_ha, EH,
  71 | 				   " Task to dev %016llx response:0x%x status 0x%x\n",
  72 | 				   SAS_ADDR(dev->sas_addr),
  73 | 				   task->task_status.resp,
  74 | 				   task->task_status.stat);
  75 | 			sas_free_task(task);
  76 | 			task = NULL;
  77 | 		}
  78 | 	}
  79 | ex_err:
  80 | 	BUG_ON(retry == 3 && task != NULL);
  81 | 	sas_free_task(task);
  82 | 	return res;
  83 | }
</VERSION_A>

