   1 | modify_bar_registration(struct pci_vdev *dev, int idx, int registration)
   2 | {
   3 | 	int error;
   4 | 	struct inout_port iop;
   5 | 	struct mem_range mr;
   6 | 
   7 | 	if (is_pci_gvt(dev)) {
   8 | 		/* GVT device is the only one who traps the pci bar access and
   9 | 		 * intercepts the corresponding contents in kernel. It needs
  10 | 		 * register pci resource only, but no need to register the
  11 | 		 * region.
  12 | 		 *
  13 | 		 * FIXME: This is a short term solution. This patch will be
  14 | 		 * obsoleted with the migration of using OVMF to do bar
  15 | 		 * addressing and generate ACPI PCI resource from using
  16 | 		 * acrn-dm.
  17 | 		 */
  18 | 		printf("modify_bar_registration: bypass for pci-gvt\n");
  19 | 		return 0;
  20 | 	}
  21 | 	switch (dev->bar[idx].type) {
  22 | 	case PCIBAR_IO:
  23 | 		bzero(&iop, sizeof(struct inout_port));
  24 | 		iop.name = dev->name;
  25 | 		iop.port = dev->bar[idx].addr;
  26 | 		iop.size = dev->bar[idx].size;
  27 | 		if (registration) {
  28 | 			iop.flags = IOPORT_F_INOUT;
  29 | 			iop.handler = pci_emul_io_handler;
  30 | 			iop.arg = dev;
  31 | 			error = register_inout(&iop);
  32 | 		} else
  33 | 			error = unregister_inout(&iop);
  34 | 		break;
  35 | 	case PCIBAR_MEM32:
  36 | 	case PCIBAR_MEM64:
  37 | 		bzero(&mr, sizeof(struct mem_range));
  38 | 		mr.name = dev->name;
  39 | 		mr.base = dev->bar[idx].addr;
  40 | 		mr.size = dev->bar[idx].size;
  41 | 		if (registration) {
  42 | 			mr.flags = MEM_F_RW;
  43 | 			mr.handler = pci_emul_mem_handler;
  44 | 			mr.arg1 = dev;
  45 | 			mr.arg2 = idx;
  46 | 			error = register_mem(&mr);
  47 | 		} else
  48 | 			error = unregister_mem(&mr);
  49 | 		break;
  50 | 	default:
  51 | 		error = EINVAL;
  52 | 		break;
  53 | 	}
  54 | 
  55 | 	return error;
  56 | }
